        const kf = ent.overlays.find((o) => o.year === Number(y));
        if (!kf) throw new Error(`china fixes: ${id} has no keyframe ${y}`);
        const i = kf.regions.findIndex((q) => (typeof q === 'string' ? q : q.id) === rid);
        const old = i >= 0 ? kf.regions[i] : null;
        const sum = old && typeof old !== 'string' && old.ring ? checksum(old.ring) : null;
        const want = sums?.[`${id}|${rid}|${y}`];
        CN_OBSERVED[`${id}|${rid}|${y}`] = sum;
        if (!skipChecks && (want === undefined || (want === null ? sum !== null : sum === null || Math.abs(sum - want) > 1e-6))) throw new Error(`china fixes: ${id} ${rid} ${y} changed — regenerate the redraw`);
        if (!spec) {
          kf.regions = kf.regions.filter((_, j) => j !== i);
          continue;
        }
        const ps = P(spec[1]);
        const ring = ensureClockwise(ps.length === 1 ? ps[0] : mergeRings(`${id} ${y} ${rid}`, ...ps));
        const region = { id: rid, name: spec[0], ring };
        kf.regions = i >= 0 ? kf.regions.map((q, j) => (j === i ? region : q)) : [...kf.regions, region];
